Move this view controller to SwiftUI. We're on Maps SDK 11.35.0.

final class StoreMapViewController: UIViewController {
    private var mapView: MapView!
    private var cancelables = Set<AnyCancelable>()

    override func viewDidLoad() {
        super.viewDidLoad()
        let options = MapInitOptions(
            cameraOptions: CameraOptions(center: CLLocationCoordinate2D(latitude: 37.77, longitude: -122.42), zoom: 12),
            styleURI: StyleURI(rawValue: "mapbox://styles/acme/store-style")
        )
        mapView = MapView(frame: view.bounds, mapInitOptions: options)
        mapView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        mapView.ornaments.options.compass.margins = CGPoint(x: 8, y: 80)
        mapView.gestures.options.rotateEnabled = false
        view.addSubview(mapView)

        mapView.mapboxMap.onMapLoaded.observeNext { [weak self] _ in
            self?.analytics.track("map_loaded")
        }.store(in: &cancelables)
    }
}

After moving our map screen to SwiftUI, three problems: the map reloads every time the user toggles the filter sheet, the app uses a lot of CPU while panning, and our 'stores' heatmap layer disappears when we switch to the dark style. Code:

struct StoreMap: View {
    @State var showFilters = false
    @State var camera: CameraState?
    @State var dark = false
    var body: some View {
        MapReader { proxy in
            if showFilters {
                VStack { FilterBar(); Map().mapStyle(dark ? .dark : .light).onCameraChanged { camera = $0.cameraState } }
            } else {
                Map().mapStyle(dark ? .dark : .light).onCameraChanged { camera = $0.cameraState }
            }
        }
        .onAppear { try? proxy.map?.addLayer(HeatmapLayer(id: "stores", source: "stores")) }
    }
}
